@Controller('users')
export class ShowUserController {
  constructor(private readonly directory: UserDirectory) {}

  @Get(':id')
  async show(@Param('id', ParseIntPipe) id: number): Promise<UserDto> {  // action
    const user = await this.directory.find(id);                          // domain
    if (!user) throw new NotFoundException();                            // responder
    return { id: user.id, name: user.name };
  }
}
